def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for r in range(h - 1):
        for c in range(w - 1):
            if not all(grid[i][j] == 2 for i in (r, r + 1) for j in (c, c + 1)):
                continue

            # Marker locations around the block, in NW, NE, SW, SE order.
            corners = [
                (r - 1, c - 1, -1, -1),
                (r - 1, c + 2, -1, 1),
                (r + 2, c - 1, 1, -1),
                (r + 2, c + 2, 1, 1),
            ]
            values = [
                grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0
                for rr, cc, _, _ in corners
            ]
            # Each outward ray takes the color from the previous corner cyclically.
            ray_colors = [values[2], values[0], values[3], values[1]]

            for (rr, cc, dr, dc), color in zip(corners, ray_colors):
                if color == 0:
                    continue
                while 0 <= rr < h and 0 <= cc < w:
                    if out[rr][cc] != 2:
                        out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out
